CREATE TABLE IF NOT EXISTS public.expenses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE, vehicle_id uuid REFERENCES public.vehicles(id) ON DELETE SET NULL, device_id uuid REFERENCES public.gps_devices(id) ON DELETE SET NULL, created_by uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT, approved_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, amount numeric(14,2) NOT NULL CHECK (amount >= 0), tax_amount numeric(14,2) NOT NULL DEFAULT 0 CHECK (tax_amount >= 0), expense_date date NOT NULL DEFAULT CURRENT_DATE, category text NOT NULL, description text, vendor text, payment_method text, invoice_number text, receipt_url text, mileage_km numeric(12,2) CHECK (mileage_km IS NULL OR mileage_km >= 0), status text NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','APPROVED','REJECTED')), approved_at timestamptz, rejection_reason text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());